import { POLICY_DIMENSIONS, POLICY_PARAMETER_COUNT } from "@chowk/controllers";
import { VEHICLE_CLASSES } from "@chowk/sim";
import highlightsFile from "../../../../../results/highlights.json";

/** Generated by `npm run bench:readme` from the published benchmark, like the README. */
export const highlights = highlightsFile;
export type Highlights = typeof highlightsFile;

export const policyInputs = POLICY_DIMENSIONS[0];
export const policyLayers = POLICY_DIMENSIONS;
export const policyParameters = POLICY_PARAMETER_COUNT;

export const whole = new Intl.NumberFormat("en-IN");
export const oneDecimal = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
});

export function percent(value: number): string {
  return `${oneDecimal.format(Math.abs(value) * 100)}%`;
}

export function signedPercent(value: number): string {
  return `${value < 0 ? "−" : value > 0 ? "+" : ""}${percent(value)}`;
}

export type SandboxClass = "two-wheeler" | "auto-rickshaw" | "car" | "bus";

/** The simulator's assumed sizes and occupancies, so the sandbox uses the model's own numbers. */
export const vehicle = Object.fromEntries(
  VEHICLE_CLASSES.map(({ id, length, width, occupancy }) => [id, { length, width, occupancy }]),
) as Record<SandboxClass, { length: number; width: number; occupancy: number }>;

export const vehicleNames: Record<SandboxClass, string> = {
  "two-wheeler": "Two-wheeler",
  "auto-rickshaw": "Auto",
  car: "Car",
  bus: "Bus",
};
